   789              mc_connect->lwt_msg->topic_name);
   790          tx_payload += MqttEncode_Data(tx_payload,
   791              mc_connect->lwt_msg->buffer, (word16)mc_connect->lwt_msg->total_len);
   792      }
   793      if (mc_connect->username) {
   794          tx_payload += MqttEncode_String(tx_payload, mc_connect->username);
