   805  int MqttDecode_ConnectAck(byte *rx_buf, int rx_buf_len,
   806      MqttConnectAck *connect_ack)
   807  {
   808      int header_len, remain_len;
   809      byte *rx_payload;
   810
   811      /* Validate required arguments */
   812      if (rx_buf == NULL || rx_buf_len <= 0) {
   813          return MQTT_TRACE_ERROR(MQTT_CODE_ERROR_BAD_ARG);
   814      }
   815
   816      /* Decode fixed header */
   817      header_len = MqttDecode_FixedHeader(rx_buf, rx_buf_len, &remain_len,
   818          MQTT_PACKET_TYPE_CONNECT_ACK, NULL, NULL, NULL);
   819      if (header_len < 0) {
   820          return header_len;
   821      }
   822      rx_payload = &rx_buf[header_len];
   823
   824      /* Decode variable header */
   825      if (connect_ack) {
   826          connect_ack->flags = *rx_payload++;
   827          connect_ack->return_code = *rx_payload++;
   828
   829  #ifdef WOLFMQTT_V5
   830          if (connect_ack->protocol_level >= MQTT_CONNECT_PROTOCOL_LEVEL_5) {
   831              word32 props_len = 0;
   832              int tmp;
   833              /* Decode Length of Properties */
   834              tmp = MqttDecode_Vbi(rx_payload, &props_len,
   835                      (word32)(rx_buf_len - (rx_payload - rx_buf)));
   836              if (tmp < 0) {
   837                  return tmp;
   838              }
   839              rx_payload += tmp;
   840              if (props_len > 0) {
   841                  /* Decode the Properties */
   842                  tmp = MqttDecode_Props(MQTT_PACKET_TYPE_CONNECT_ACK,
   843                                 &connect_ack->props, rx_payload,
   844                                 (word32)(rx_buf_len - (rx_payload - rx_buf)),
   845                                 props_len);
   846                  if (tmp < 0)
   847                      return tmp;
   848                  rx_payload += tmp;
   849              }
   850          }
   851  #endif
   852      }
   853
   854      (void)rx_payload;
   855
   856      /* Return total length of packet */
   857      return header_len + remain_len;
   858  }
